// The site's share image and PNG icons (site/public/), generated by site/scripts/make-assets.mjs.
// These tests run without a browser and without a build: they read the generated files and the
// manifest the script writes next to it, and they rebuild the browser-free part of the script
// (tokens, copy, mark, flow lines, HTML, ICO) from today's sources.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  ASSETS,
  buildIco,
  buildIconHtml,
  buildOgHtml,
  collectSources,
  findChrome,
  flowLines,
  heroContent,
  manifestInputs,
  pngSize,
  readIco,
  readMark,
  readStrings,
  readTokens,
} from '../site/scripts/make-assets.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SITE = join(ROOT, 'site');
const PUBLIC = join(SITE, 'public');
const MANIFEST = join(SITE, 'scripts', 'assets', 'manifest.json');
const sha256 = (data) => createHash('sha256').update(data).digest('hex');
const read = (path) => readFileSync(join(SITE, path), 'utf8');

const OUTPUTS = ['og-image.png', 'favicon-32.png', 'favicon-64.png', 'apple-touch-icon.png', 'favicon.ico'];

// The test's own PNG header reader: width and height from the IHDR chunk.
function headerSize(buffer) {
  const signature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  assert.ok(buffer.subarray(0, 8).equals(signature), 'not a PNG signature');
  assert.equal(buffer.toString('latin1', 12, 16), 'IHDR');
  return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
}

// RGB triples of every colour literal in a piece of CSS or HTML: hex and rgb()/rgba().
function colourLiterals(text) {
  const found = [];
  for (const m of text.matchAll(/#([0-9a-fA-F]{3,8})\b/g)) {
    let h = m[1];
    if (h.length === 3 || h.length === 4) h = [...h.slice(0, 3)].map((c) => c + c).join('');
    found.push({ literal: m[0], rgb: [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16)).join(',') });
  }
  for (const m of text.matchAll(/rgba?\(([^)]*)\)/g)) {
    const parts = m[1].split(/[\s,/]+/).filter(Boolean).slice(0, 3).map(Number);
    found.push({ literal: m[0], rgb: parts.join(',') });
  }
  return found;
}

const withoutDataUrls = (html) => html.replace(/data:[a-z/0-9+.-]+;base64,[A-Za-z0-9+/=]+/g, '');

test('each generated PNG has the size its header declares and the site expects', () => {
  const expected = {
    'og-image.png': [1600, 900],
    'favicon-32.png': [32, 32],
    'favicon-64.png': [64, 64],
    'apple-touch-icon.png': [180, 180],
  };
  for (const [file, [width, height]] of Object.entries(expected)) {
    assert.deepEqual(headerSize(readFileSync(join(PUBLIC, file))), { width, height }, file);
  }
});

test('the share image has the dimensions Layout.astro declares', () => {
  const layout = read('src/layouts/Layout.astro');
  const width = Number(/og:image:width"\s+content="(\d+)"/.exec(layout)?.[1]);
  const height = Number(/og:image:height"\s+content="(\d+)"/.exec(layout)?.[1]);
  assert.ok(width > 0 && height > 0, 'Layout.astro declares no og:image size');
  assert.deepEqual(headerSize(readFileSync(join(PUBLIC, 'og-image.png'))), { width, height });
});

test('favicon.ico is a valid ICO container carrying the 32 px PNG', () => {
  const ico = readFileSync(join(PUBLIC, 'favicon.ico'));
  assert.equal(ico.readUInt16LE(0), 0, 'reserved field');
  assert.equal(ico.readUInt16LE(2), 1, 'type 1 is icon');
  assert.equal(ico.readUInt16LE(4), 1, 'one image');
  assert.equal(ico[6], 32, 'entry width');
  assert.equal(ico[7], 32, 'entry height');
  assert.equal(ico.readUInt16LE(10), 1, 'colour planes');
  assert.equal(ico.readUInt16LE(12), 32, 'bits per pixel');
  const size = ico.readUInt32LE(14);
  const offset = ico.readUInt32LE(18);
  assert.equal(offset, 22);
  assert.equal(offset + size, ico.length, 'the image runs to the end of the file');
  const png = ico.subarray(offset, offset + size);
  assert.deepEqual(headerSize(png), { width: 32, height: 32 });
  assert.ok(png.equals(readFileSync(join(PUBLIC, 'favicon-32.png'))), 'the ICO carries favicon-32.png');
});

test('every generated file is the one the script produced last', () => {
  assert.ok(existsSync(MANIFEST), 'site/scripts/assets/manifest.json is missing: run node site/scripts/make-assets.mjs');
  const manifest = JSON.parse(readFileSync(MANIFEST, 'utf8'));
  assert.deepEqual(Object.keys(manifest.outputs).sort(), [...OUTPUTS].sort());
  for (const file of OUTPUTS) {
    assert.equal(sha256(readFileSync(join(PUBLIC, file))), manifest.outputs[file], `${file} differs from the manifest`);
  }
});

test('the manifest is current with today\'s copy, mark, tokens and HTML', () => {
  const manifest = JSON.parse(readFileSync(MANIFEST, 'utf8'));
  const sources = collectSources(SITE);
  assert.deepEqual(manifest.inputs, manifestInputs(sources), 'a source changed: run node site/scripts/make-assets.mjs');
  // Read the same facts here independently of the script, so a reader bug cannot hide a change.
  const en = read('src/i18n/en.ts');
  const title = /heroTitle:\s*'([^']*)'/.exec(en)[1].replace(/\\n/g, '\n');
  assert.equal(manifest.inputs.title, title);
  assert.equal(manifest.inputs.notes.before, /heroFlowBefore:\s*'([^']*)'/.exec(en)[1]);
  assert.equal(manifest.inputs.notes.after, /heroFlowAfter:\s*'([^']*)'/.exec(en)[1]);
  assert.equal(manifest.inputs.mark, /<path d="([^"]+)"/.exec(read('public/favicon.svg'))[1]);
  const css = read('src/styles/genius/genius-tudo.css');
  assert.equal(manifest.inputs.colors.accent, /--violet:\s*([^;]+);/.exec(css)[1].trim());
  assert.equal(manifest.inputs.colors.bg, /--bg:\s*([^;]+);/.exec(css)[1].trim());
  for (const asset of ASSETS) {
    assert.equal(manifest.html[asset.file], sha256(asset.html(sources)), `${asset.file}: the HTML it comes from changed`);
  }
});

test('readTokens resolves the violet accent and var() references', () => {
  const css = ':root { --a: #111111; --b: var(--a); --accent: var(--acid); --acid: #222222; --x: rgb(1 2 3 / 0.5); }\n'
    + '[data-gx-acento="violet"] { --accent: var(--violet); }\n:root { --violet: #333333; }';
  const tokens = readTokens(css);
  assert.equal(tokens['--b'], '#111111');
  assert.equal(tokens['--accent'], '#333333');
  assert.equal(tokens['--x'], 'rgb(1 2 3 / 0.5)');
});

test('readStrings, readMark and heroContent take the copy as the hero shows it', () => {
  const strings = readStrings("export default {\n  a: 'one\\ntwo',\n  b: 'it\\'s',\n};");
  assert.deepEqual(strings, { a: 'one\ntwo', b: "it's" });
  assert.equal(readMark('<svg><path d="M1 2 L3 4"/></svg>'), 'M1 2 L3 4');
  const content = heroContent({
    heroTitle: 'Spec-driven development\nfor AI agents',
    heroFlowBefore: 'no spec',
    heroFlowAfter: 'with a spec',
    heroQuickStart2Cmd: '$ gen-spec "auth"',
    heroQuickStart2Desc: '✓ 5 DoD checks · budget ≤4 files · anti-scope locked',
    heroQuickStart4Desc: 'PASS. All checks verified, patterns followed',
  });
  assert.deepEqual(content.titleLines, [
    { before: '', term: 'Spec-driven', after: ' development' },
    { before: 'for AI agents', term: '', after: '' },
  ]);
  assert.deepEqual(content.notes, { before: 'no spec', after: 'with a spec' });
  assert.deepEqual(content.card, { label: 'spec · auth', items: ['5 DoD checks', 'budget ≤4 files', 'anti-scope locked'] });
  assert.equal(content.verdict, 'PASS');
});

test('the share image HTML has no colour literal other than the token values', () => {
  const sources = collectSources(SITE);
  const allowed = new Set(colourLiterals(Object.values(sources.palette).join(' ')).map((c) => c.rgb));
  for (const asset of ASSETS) {
    const html = withoutDataUrls(asset.html(sources));
    for (const { literal, rgb } of colourLiterals(html)) {
      assert.ok(allowed.has(rgb), `${asset.file}: ${literal} does not come from a token`);
    }
    assert.doesNotMatch(html, /\b(black|white)\b/i, `${asset.file}: named colour`);
  }
  const og = buildOgHtml(sources);
  assert.ok(og.includes(sources.palette.accent), 'the accent is used');
  assert.ok(og.includes(sources.mark), 'the mark is the favicon stroke');
  for (const text of ['no spec', 'with a spec', 'PASS', 'Spec-driven', 'for AI agents']) assert.ok(og.includes(text), text);
  assert.ok(buildIconHtml(32, sources).includes(sources.mark));
});

test('the flow lines run to the right edge and come out parallel past the gate', () => {
  const W = 1600;
  const H = 350;
  const lines = flowLines(W, H);
  assert.ok(lines.length > 10);
  const past = 0.54 * W; // the spec card sits on the gate; heroGeometry orders the lines before it
  const ys = lines.map((points) => {
    assert.equal(points[0][0], 0, 'starts at the left edge');
    assert.equal(points.at(-1)[0], W, 'ends at the right edge');
    const after = points.filter(([x]) => x >= past);
    const first = after[0][1];
    for (const [, y] of after) assert.ok(Math.abs(y - first) < 1e-6, 'flat past the gate');
    return first;
  });
  const gaps = ys.slice(1).map((y, i) => y - ys[i]);
  for (const g of gaps) assert.ok(Math.abs(g - gaps[0]) < 1e-6 && g > 0, 'evenly spaced');
});

test('buildIco and readIco round-trip the PNG that went in', () => {
  const png = readFileSync(join(PUBLIC, 'favicon-32.png'));
  const ico = buildIco([png]);
  const [entry] = readIco(ico);
  assert.ok(entry.data.equals(png));
  assert.deepEqual([entry.width, entry.height], [32, 32]);
  assert.deepEqual(pngSize(png), { width: 32, height: 32 });
});

test('findChrome prefers the environment variable and reports nothing when no browser exists', () => {
  assert.equal(findChrome({ CHROME_PATH: '/opt/x/chrome' }, (p) => p === '/opt/x/chrome'), '/opt/x/chrome');
  assert.equal(findChrome({}, () => false), null);
  const seen = [];
  findChrome({}, (p) => { seen.push(p); return false; });
  assert.ok(seen.some((p) => p.startsWith('/Applications/')), 'macOS location');
  assert.ok(seen.some((p) => p.startsWith('/usr/bin/')), 'Linux location');
  for (const p of seen) assert.doesNotMatch(p, /^\/(Users|home)\//, 'no personal path');
});
